#!/usr/bin/env python3
"""run-dev-graph-sync (C03) one-pass driver for the r5-sync offline live trial.

Implements R1-elicit .. R8-scheduled against the deterministic fixture adapter.
Every external write is routed through gh-bridge.py with DEV_GRAPH_GH pinned to the
fixture's offline fake-gh, so no network GitHub endpoint is reachable by construction.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import subprocess
import sys
from pathlib import Path

PLUGIN_SCRIPTS = Path(__file__).resolve()  # replaced by --scripts


class Fail(Exception):
    pass


def sh(argv: list[str], env: dict | None = None) -> str:
    cp = subprocess.run(argv, capture_output=True, text=True, env=env)
    if cp.returncode != 0:
        raise Fail(f"command failed ({cp.returncode}): {' '.join(argv)}\n{cp.stderr.strip()}")
    return cp.stdout


def jsh(argv: list[str], env: dict | None = None):
    return json.loads(sh(argv, env))


def digest(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def file_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_json(path: Path):
    return json.loads(path.read_text(encoding="utf-8"))


def atomic_write_json(path: Path, payload) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2) + "\n", encoding="utf-8")
    os.replace(tmp, path)


def atomic_write_text(path: Path, text: str) -> None:
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(text, encoding="utf-8")
    os.replace(tmp, path)


def split_frontmatter(text: str) -> tuple[list[str], str]:
    if not text.startswith("---\n"):
        raise Fail("task markdown is missing frontmatter")
    end = text.index("\n---\n", 3)
    return text[4:end + 1].splitlines(True), text[end + 5:]


def set_frontmatter_scalar(lines: list[str], key: str, value: str) -> list[str]:
    out, done = [], False
    for line in lines:
        if not done and line.startswith(f"{key}:"):
            out.append(f'{key}: "{value}"\n')
            done = True
        else:
            out.append(line)
    if not done:
        raise Fail(f"frontmatter key not found: {key}")
    return out


def issue_body_projection(repo: str) -> str:
    """Canonical, deterministic Issue body projection for this fixture repository.

    The projection is a pure function of the issue repository slug, so re-running the
    sync never produces body churn (base snapshot body_digest stays stable)."""
    return f"dev-graph fixture task body. Managed by the offline {repo.split('/')[-1]} adapter fixture."


def local_project_fields(node: dict, mappings: list[dict]) -> dict:
    values = {}
    for mapping in mappings:
        local_value = node.get(mapping["local_field"])
        if local_value is None:
            continue
        if mapping["value_type"] == "single_select":
            mapped = mapping["option_map"].get(str(local_value))
            if mapped is None:
                raise Fail(f"unmapped option for {mapping['local_field']}={local_value}")
            values[mapping["project_field_name"]] = mapped
        else:
            values[mapping["project_field_name"]] = str(local_value)
    return values


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo-root", required=True)
    ap.add_argument("--binding", required=True, choices=("github", "beads", "none"))
    ap.add_argument("--adapter-fixture", required=True)
    ap.add_argument("--scripts", required=True)
    ap.add_argument("--pass-index", type=int, required=True)
    ap.add_argument("--dry-run", action="store_true")
    a = ap.parse_args()

    scripts = Path(a.scripts).resolve()
    gh_bridge = str(scripts / "gh-bridge.py")

    # ---------- C24 context (fail-closed containment) ----------
    receipt = jsh([sys.executable, str(scripts / "resolve-repo-context.py"),
                   "--repo-root", a.repo_root, "--mode", "write"])
    root = Path(receipt["repo_root"]).resolve()
    if root != Path(receipt["content_roots"]["repository"]).resolve():
        raise Fail("repo_root does not match content_roots.repository")
    adapter_path = Path(a.adapter_fixture).resolve()
    if root not in adapter_path.parents:
        raise Fail("adapter fixture is outside the caller repository")
    fake_gh = root / "tools" / "fake-gh.py"
    if not fake_gh.is_file():
        raise Fail("offline adapter entry point is missing")
    env = {**os.environ, "DEV_GRAPH_GH": str(fake_gh)}

    graph_path = Path(receipt["local_state_paths"]["graph"])
    config_path = Path(receipt["local_state_paths"]["config"])
    snapshot_path = root / ".dev-graph/state/github-sync-snapshot.json"
    call_log = root / "github-adapter-calls.jsonl"

    def call_log_lines() -> list[dict]:
        if not call_log.is_file():
            return []
        return [json.loads(line) for line in call_log.read_text(encoding="utf-8").splitlines() if line.strip()]

    before = {
        "graph": file_digest(graph_path),
        "snapshot": file_digest(snapshot_path),
        "adapter": file_digest(adapter_path),
        "config": file_digest(config_path),
    }
    before_calls = len(call_log_lines())
    before_mutations = len(read_json(adapter_path)["mutation_log"])

    # ---------- IN1: schema validation before any send ----------
    validation = jsh([sys.executable, str(scripts / "validate-graph-schema.py"),
                      "--graph", str(graph_path), "--repo-root", str(root)])
    if not validation["valid"] or validation["violations"]:
        raise Fail(f"graph schema validation failed: {validation['violations']}")

    config = read_json(config_path)
    graph = read_json(graph_path)
    snapshot = read_json(snapshot_path)
    adapter_clock = read_json(adapter_path)["clock"]
    now = adapter_clock["sync_run_at"]

    # ---------- R1-elicit ----------
    if config.get("execution_tracker", {}).get("mode") != a.binding:
        raise Fail("binding does not match repo config execution_tracker.mode")
    gh_config = config["github"]
    if not gh_config.get("enabled"):
        raise Fail("github tracker is not enabled in repo config")
    issue_repo = gh_config["issue_repository"]
    targets = {}
    for project in gh_config["projects"]:
        for key in ("alias", "owner_login", "owner_type", "project_number", "field_mappings"):
            if project.get(key) in (None, ""):
                raise Fail(f"project target is missing {key}")
        resolved = jsh([sys.executable, gh_bridge, "--op", "project-resolve",
                        "--owner", project["owner_login"],
                        "--project-number", str(project["project_number"])], env)["result"]
        field_ids = {f["name"]: f for f in resolved["fields"]["nodes"]}
        for mapping in project["field_mappings"]:
            if mapping["project_field_name"] not in field_ids:
                raise Fail(f"project field missing on remote: {mapping['project_field_name']}")
        targets[project["alias"]] = {
            "config": project,
            "project_id": resolved["id"],          # runtime-resolved, never persisted to config
            "fields": field_ids,
        }
    elicit = {
        "issue_repository": issue_repo,
        "aliases": sorted(targets),
        "default_alias": next(p["alias"] for p in gh_config["projects"] if p.get("default")),
        "runtime_ids_persisted_to_config": False,
        "missing_target_fields": 0,
    }

    # ---------- authority partition ----------
    nodes = [n for n in graph["nodes"] if n["artifact_kind"] == "task"]
    bound = [n for n in nodes if n.get("tracker_binding") == "github"]
    for node in bound:
        if node.get("beads_linkage") is not None:
            raise Fail(f"mixed authority: {node['graph_node_id']} has beads_linkage under github binding")
    authority = {"github": [n["graph_node_id"] for n in bound],
                 "beads": [n["graph_node_id"] for n in nodes if n.get("tracker_binding") == "beads"],
                 "none": [n["graph_node_id"] for n in nodes if n.get("tracker_binding") == "none"]}

    # ---------- R2-plan: 3-way diff against the last-synced base ----------
    body = issue_body_projection(issue_repo)
    body_digest = digest(body)
    plan = []
    for node in sorted(bound, key=lambda n: n["graph_node_id"]):
        nid = node["graph_node_id"]
        linkage = node.get("issue_linkage")
        if not linkage:
            raise Fail(f"{nid} has no issue linkage; creation path is out of scenario scope")
        base = snapshot["issues"].get(nid)
        if base is None:
            raise Fail(f"{nid} has no last-synced base entry")
        remote = jsh([sys.executable, gh_bridge, "--op", "issue-fetch",
                      "--repo", issue_repo, "--number", str(linkage["issue_number"])], env)["result"]
        if remote["id"] != base["issue_node_id"]:
            raise Fail(f"{nid} remote issue node id drifted")
        local_changed = node["title"] != base["title"] or body_digest != base["body_digest"]
        remote_changed = (remote["title"] != base["title"]
                          or remote["state"] != base["state"]
                          or remote["updated_at"] != base["remote_updated_at"])
        entry = {
            "graph_node_id": nid, "issue_number": linkage["issue_number"],
            "issue_node_id": remote["id"],
            "local": {"title": node["title"], "updated_at": node["updated_at"], "body_digest": body_digest},
            "remote": {"title": remote["title"], "state": remote["state"], "updated_at": remote["updated_at"]},
            "base": {"title": base["title"], "state": base["state"],
                     "local_updated_at": base["local_updated_at"], "remote_updated_at": base["remote_updated_at"],
                     "body_digest": base["body_digest"]},
            "issue": {}, "projects": {},
        }
        if local_changed and remote_changed:
            if node["updated_at"] == remote["updated_at"]:
                entry["issue"] = {"classification": "manual_conflict", "tie_break": "github_display_value",
                                  "confirmation_flag": True}
            else:
                newer = "local" if node["updated_at"] > remote["updated_at"] else "remote"
                entry["issue"] = {"classification": "manual_conflict", "tie_break": f"{newer}_is_newer",
                                  "confirmation_flag": True}
        elif local_changed:
            entry["issue"] = {"classification": "local_only", "direction": "export",
                              "operation": "issue-update", "title": node["title"]}
        elif remote_changed:
            if remote["state"] == "closed" and base["state"] != "closed":
                entry["issue"] = {"classification": "remote_only", "direction": "import",
                                  "operation": "tombstone_status_transition", "title": remote["title"]}
            else:
                entry["issue"] = {"classification": "remote_only", "direction": "import",
                                  "operation": "local-title-import", "title": remote["title"]}
        else:
            entry["issue"] = {"classification": "unchanged"}

        # Projects: field-level 3-way using field_snapshot base + remote field updatedAt hints
        for alias, target in sorted(targets.items()):
            if alias not in (node.get("github_publication") or {}).get("project_aliases", []):
                continue
            mappings = target["config"]["field_mappings"]
            gate = target["config"].get("auto_add", {})
            eligible = (node.get("confirmation_status") == gate.get("confirmation_status")
                        and node.get("evaluation_status") == gate.get("evaluation_status")
                        and (node.get("implementation_readiness") or {}).get("status") == gate.get("implementation_readiness")
                        and node["artifact_kind"] in gate.get("artifact_kinds", []))
            found = jsh([sys.executable, gh_bridge, "--op", "project-item-find",
                         "--project-id", target["project_id"], "--content-id", remote["id"]], env)["result"]
            items = found["items"]
            if len(items) > 1:
                raise Fail(f"{nid}/{alias} has duplicate project items")
            link = next((l for l in node.get("github_project_linkages", []) if l["project_alias"] == alias), None)
            item_id = items[0]["id"] if items else None
            if link and item_id and link["item_id"] != item_id:
                raise Fail(f"{nid}/{alias} project item id is unstable")
            base_fields = dict((link or {}).get("field_snapshot", {}))
            remote_item = next((i for i in read_json(adapter_path)["projects"][alias]["items"]
                                if i["id"] == item_id), None) if item_id else None
            remote_fields = dict((remote_item or {}).get("fields", {}))
            local_fields = local_project_fields(node, mappings)
            field_plan = {}
            for mapping in mappings:
                name = mapping["project_field_name"]
                lv, rv, bv = local_fields.get(name), remote_fields.get(name), base_fields.get(name)
                lchanged, rchanged = lv != bv, rv != bv
                if mapping["direction"] == "local_to_project":
                    # Status/date never flow back; remote drift is re-projected from local.
                    if lchanged or (rchanged and lv != rv):
                        field_plan[name] = {"classification": "local_only", "direction": "local_to_project",
                                            "to": lv, "remote_import_suppressed": rchanged}
                    else:
                        field_plan[name] = {"classification": "unchanged"}
                else:
                    if lchanged and rchanged and lv != rv:
                        field_plan[name] = {"classification": "manual_conflict", "local": lv, "remote": rv}
                    elif lchanged and lv != rv:
                        field_plan[name] = {"classification": "local_only", "direction": "local_to_project", "to": lv}
                    elif rchanged and lv != rv:
                        field_plan[name] = {"classification": "remote_only", "direction": "project_to_local",
                                            "to": rv}
                    else:
                        field_plan[name] = {"classification": "unchanged"}
            entry["projects"][alias] = {
                "auto_add_eligible": eligible,
                "item_id": item_id,
                "item_add_required": eligible and item_id is None,
                "pages_scanned": found["pages"],
                "fields": field_plan,
            }
        plan.append(entry)

    planned = {
        "imports": [e for e in plan if e["issue"].get("direction") == "import"],
        "exports": [e for e in plan if e["issue"].get("direction") == "export"],
        "conflicts": [e for e in plan if e["issue"].get("classification") == "manual_conflict"],
        "tombstones": [e for e in plan if e["issue"].get("operation") == "tombstone_status_transition"],
        "item_adds": [(e["graph_node_id"], alias) for e in plan for alias, p in e["projects"].items()
                      if p["item_add_required"]],
        "field_ops": [(e["graph_node_id"], alias, name, fp) for e in plan for alias, p in e["projects"].items()
                      for name, fp in p["fields"].items() if fp["classification"] != "unchanged"],
    }
    unclassified = [e["graph_node_id"] for e in plan if not e["issue"].get("classification")]
    if unclassified:
        raise Fail(f"unclassified diff entries: {unclassified}")

    applied: list[dict] = []
    pending_retry: list[dict] = []

    # ---------- R5-dryrun: preview only, zero mutations ----------
    if a.dry_run:
        previews = []
        for e in planned["exports"]:
            previews.append(jsh([sys.executable, gh_bridge, "--op", "issue-update", "--repo", issue_repo,
                                 "--number", str(e["issue_number"]), "--title", e["issue"]["title"],
                                 "--body", body, "--dry-run"], env))
        for nid, alias in planned["item_adds"]:
            previews.append(jsh([sys.executable, gh_bridge, "--op", "project-item-add",
                                 "--project-id", targets[alias]["project_id"], "--content-id",
                                 next(e["issue_node_id"] for e in plan if e["graph_node_id"] == nid),
                                 "--dry-run"], env))
        for nid, alias, name, fp in planned["field_ops"]:
            previews.append({"op": "project-item-edit", "dry_run": True, "mutation_suppressed": True,
                             "preview": {"alias": alias, "graph_node_id": nid, "field": name, "plan": fp}})
        if any(not p.get("mutation_suppressed") for p in previews):
            raise Fail("dry-run preview leaked a mutation")
    else:
        # ---------- R3-sync: apply exports then imports through C12 only ----------
        for e in planned["exports"]:
            jsh([sys.executable, gh_bridge, "--op", "issue-update", "--repo", issue_repo,
                 "--number", str(e["issue_number"]), "--title", e["issue"]["title"], "--body", body], env)
            fetched = jsh([sys.executable, gh_bridge, "--op", "issue-fetch", "--repo", issue_repo,
                           "--number", str(e["issue_number"])], env)["result"]
            snapshot["issues"][e["graph_node_id"]] = {
                "body_digest": body_digest, "issue_node_id": fetched["id"],
                "issue_number": fetched["number"],
                "local_updated_at": e["local"]["updated_at"], "remote_updated_at": fetched["updated_at"],
                "state": fetched["state"], "title": e["issue"]["title"],
            }
            applied.append({"kind": "export", "graph_node_id": e["graph_node_id"],
                            "operation": "issue-update", "title": e["issue"]["title"],
                            "remote_updated_at": fetched["updated_at"]})

        for e in planned["imports"]:
            node = next(n for n in graph["nodes"] if n["graph_node_id"] == e["graph_node_id"])
            task_file = root / node["file_path"]
            lines, rest = split_frontmatter(task_file.read_text(encoding="utf-8"))
            lines = set_frontmatter_scalar(lines, "title", e["issue"]["title"])
            if e["issue"]["operation"] == "tombstone_status_transition":
                # C02 semantics: never delete the node, only transition status/closed_at.
                lines = set_frontmatter_scalar(lines, "status", "done" if False else "closed")
                node["status"] = "closed"
                node["closed_at"] = now
            lines = set_frontmatter_scalar(lines, "updated_at", now)
            node["title"] = e["issue"]["title"]
            node["updated_at"] = now
            atomic_write_text(task_file, "---\n" + "".join(lines) + "---\n" + rest)
            snapshot["issues"][e["graph_node_id"]] = {
                "body_digest": body_digest, "issue_node_id": e["issue_node_id"],
                "issue_number": e["issue_number"], "local_updated_at": now,
                "remote_updated_at": e["remote"]["updated_at"], "state": e["remote"]["state"],
                "title": e["issue"]["title"],
            }
            applied.append({"kind": "import", "graph_node_id": e["graph_node_id"],
                            "operation": e["issue"]["operation"], "title": e["issue"]["title"],
                            "node_deleted": False})

        for nid, alias in planned["item_adds"]:
            content_id = next(e["issue_node_id"] for e in plan if e["graph_node_id"] == nid)
            try:
                result = jsh([sys.executable, gh_bridge, "--op", "project-item-add",
                              "--project-id", targets[alias]["project_id"], "--content-id", content_id], env)
                applied.append({"kind": "project_item_add", "graph_node_id": nid, "alias": alias,
                                "item_id": result["result"]["data"]["addProjectV2ItemById"]["item"]["id"]})
            except Fail as exc:  # partial remote failure never rolls local promotion back
                pending_retry.append({"graph_node_id": nid, "alias": alias, "op": "project-item-add",
                                      "error": str(exc)[:200]})

        for nid, alias, name, fp in planned["field_ops"]:
            if fp["classification"] == "manual_conflict":
                continue
            target = targets[alias]
            field = target["fields"][name]
            option = next((o for o in field.get("options", []) if o["name"] == fp["to"]), None)
            if option is None:
                pending_retry.append({"graph_node_id": nid, "alias": alias, "op": "project-item-edit",
                                      "field": name, "error": "option_missing"})
                continue
            item_id = next(e["projects"][alias]["item_id"] for e in plan if e["graph_node_id"] == nid)
            try:
                jsh([sys.executable, gh_bridge, "--op", "project-item-edit",
                     "--project-id", target["project_id"], "--item-id", item_id,
                     "--field-id", field["id"], "--option-id", option["id"]], env)
                node = next(n for n in graph["nodes"] if n["graph_node_id"] == nid)
                link = next(l for l in node["github_project_linkages"] if l["project_alias"] == alias)
                link["field_snapshot"][name] = fp["to"]
                link["last_synced_at"] = now
                snapshot["projects"][nid][alias]["field_updated_at"][name] = now
                applied.append({"kind": "project_field_edit", "graph_node_id": nid, "alias": alias,
                                "field": name, "to": fp["to"]})
            except Fail as exc:
                pending_retry.append({"graph_node_id": nid, "alias": alias, "op": "project-item-edit",
                                      "field": name, "error": str(exc)[:200]})

        # ---------- R6-confirm: persist / clear manual confirmation flags ----------
        flags = {e["graph_node_id"]: {"reason": "issue_id_updated_at_conflict",
                                      "tie_break": e["issue"].get("tie_break"),
                                      "github_display_value": e["remote"]["title"],
                                      "local_value": e["local"]["title"], "raised_at": now}
                 for e in planned["conflicts"]}
        flag_path = root / ".dev-graph/state/sync-confirmations.json"
        prior = read_json(flag_path).get("pending", {}) if flag_path.is_file() else {}
        resolved_flags = [nid for nid in prior if nid not in flags]
        if flags or prior:
            atomic_write_json(flag_path, {"schema_version": "1.0.0", "binding": "github", "pending": flags})

        snapshot["last_synced_at"] = now
        if planned["exports"] or planned["imports"] or planned["field_ops"] or planned["item_adds"]:
            graph["graph_revision"] = graph.get("graph_revision", 0) + 1
        atomic_write_json(snapshot_path, snapshot)
        atomic_write_json(graph_path, graph)

        post = jsh([sys.executable, str(scripts / "validate-graph-schema.py"),
                    "--graph", str(graph_path), "--repo-root", str(root)])
        if not post["valid"] or post["violations"]:
            raise Fail(f"post-apply schema validation failed: {post['violations']}")

    # ---------- R7-lifecycle (C26/C27) ----------
    lifecycle = jsh([sys.executable, str(scripts / "reconcile-github-lifecycle.py"),
                     "--repo-root", str(root), "--mode", "drain-pending",
                     "--gh-bridge", gh_bridge], env)

    # ---------- R8-scheduled ----------
    sched = config["github"]["completion_policy"]["scheduled_reconciliation"]
    scheduled = {
        "enabled": sched["enabled"], "owner": sched["owner"], "entry_point": sched["entry_point"],
        "interval_minutes": sched["interval_minutes"],
        "invoked_via": "manual_sync" if sched["owner"] == "claude_session_start" else "host_scheduler",
        "c26_invocations_this_pass": 1,
        "idempotency_key": f'{receipt["repository_id"]}:{sched["entry_point"]}:{now}',
    }

    after = {
        "graph": file_digest(graph_path),
        "snapshot": file_digest(snapshot_path),
        "adapter": file_digest(adapter_path),
        "config": file_digest(config_path),
    }
    if after["config"] != before["config"]:
        raise Fail("repo config must not be mutated by sync")
    calls = call_log_lines()[before_calls:]
    mutations_after = len(read_json(adapter_path)["mutation_log"])

    if a.dry_run:
        for key in ("graph", "snapshot", "adapter"):
            if before[key] != after[key]:
                raise Fail(f"dry-run mutated {key}")
        if any(c["mutation"] for c in calls) or mutations_after != before_mutations:
            raise Fail("dry-run performed an external mutation")

    out = {
        "pass_index": a.pass_index,
        "dry_run": a.dry_run,
        "binding": a.binding,
        "scenario_id": "C03-OUT1-positive-second-sync-zero",
        "repo_root_relative": ".",
        "adapter_fixture": str(adapter_path.relative_to(root)),
        "network": read_json(adapter_path)["network"],
        "elicit": elicit,
        "authority": authority,
        "schema_validation": {"pre": {"valid": validation["valid"], "violations": validation["violations"]}},
        "plan": plan,
        "changes": {
            "imports": len(planned["imports"]),
            "exports": len(planned["exports"]),
            "project_item_adds": len(planned["item_adds"]),
            "project_field_edits": len([f for f in planned["field_ops"] if f[3]["classification"] != "manual_conflict"]),
            "conflicts": len(planned["conflicts"]),
            "tombstones": len(planned["tombstones"]),
            "pending_retry": len(pending_retry),
        },
        "applied": applied,
        "pending_retry": pending_retry,
        "writes": {
            "gh_calls": len(calls),
            "gh_mutating_calls": sum(1 for c in calls if c["mutation"]),
            "adapter_mutation_log_delta": mutations_after - before_mutations,
            "local_files_changed": sorted(k for k in ("graph", "snapshot") if before[k] != after[k]),
        },
        "stable_ids": {
            e["graph_node_id"]: {
                "issue_node_id": e["issue_node_id"], "issue_number": e["issue_number"],
                "project_items": {alias: p["item_id"] for alias, p in e["projects"].items()},
            } for e in plan
        },
        "digests": {"before": before, "after": after},
        "lifecycle": lifecycle,
        "scheduled": scheduled,
        "manual_confirmations_pending": len(planned["conflicts"]),
    }
    print(json.dumps(out, ensure_ascii=False, sort_keys=True, indent=2))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Fail as exc:
        print(f"sync_pass: {exc}", file=sys.stderr)
        raise SystemExit(1)

