input.command:
R=/Users/dm/dev/dev/個人開発/harness; F=$R/eval-log/dev-graph/live-trial-fixtures/r5-sync; W=/private/tmp/claude-501/-Users-dm-dev-dev------harness/5b7624f5-671b-42be-9cf3-497fc13b62f1/scratchpad; python3 - "$F" "$W" <<'PY'
import hashlib, json, sys
from pathlib import Path
F, W = Path(sys.argv[1]), Path(sys.argv[2])
p0 = json.loads((F/"eval-log/run-dev-graph-sync-pass-0-dryrun.json").read_text(encoding="utf-8"))
p1 = json.loads((F/"eval-log/run-dev-graph-sync-pass-1.json").read_text(encoding="utf-8"))
p2 = json.loads((F/"eval-log/run-dev-graph-sync-pass-2.json").read_text(encoding="utf-8"))
def d(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
checks, failures = {}, []
# 1. byte-identical state after pass 2
pairs = [(".dev-graph/state/graph.json","graph.json"), (".dev-graph/state/github-sync-snapshot.json","github-sync-snapshot.json"),
         ("github-adapter.json","github-adapter.json"), ("tasks/T-SYNC-001.md","T-SYNC-001.md"), ("tasks/T-SYNC-002.md","T-SYNC-002.md")]
same = {rel: d(F/rel) == d(W/"post1"/name) for rel, name in pairs}
checks["state_unchanged_after_pass2"] = same
if not all(same.values()): failures.append(f"state changed in pass 2: {same}")
# 2. pass 1 actually changed the things it should have (and only those)
changed_by_pass1 = {rel: d(W/"pre"/name) != d(W/"post1"/name) for rel, name in pairs}
checks["changed_by_pass1"] = changed_by_pass1
if not (changed_by_pass1[".dev-graph/state/graph.json"] and changed_by_pass1["tasks/T-SYNC-001.md"]
        and changed_by_pass1["github-adapter.json"] and changed_by_pass1[".dev-graph/state/github-sync-snapshot.json"]):
    failures.append("pass 1 did not apply the expected import/export writes")
if changed_by_pass1["tasks/T-SYNC-002.md"]: failures.append("export must not rewrite the local task file")
# 3. changes counters
checks["counts"] = {"pass1": p1["changes"], "pass2": p2["changes"], "dry_run": p0["changes"]}
if (p1["changes"]["imports"], p1["changes"]["exports"], p1["changes"]["project_item_adds"]) != (1,1,0):
    failures.append("pass 1 counts != (1 import, 1 export, 0 adds)")
if any(p2["changes"][k] for k in ("imports","exports","project_item_adds","project_field_edits","conflicts","tombstones","pending_retry")):
    failures.append("pass 2 is not zero-change")
if p2["writes"]["gh_mutating_calls"] or p2["writes"]["adapter_mutation_log_delta"]:
    failures.append("pass 2 performed an external mutation")
if p0["writes"]["gh_mutating_calls"] or p0["writes"]["adapter_mutation_log_delta"] or p0["writes"]["local_files_changed"]:
    failures.append("dry-run performed a write")
# 4. stable IDs
checks["stable_ids_equal"] = p1["stable_ids"] == p2["stable_ids"]
if not checks["stable_ids_equal"]: failures.append("stable IDs drifted between passes")
# 5. 3-way base preserved: pass2 base == snapshot written by pass1, and every entry classified
snap = json.loads((F/".dev-graph/state/github-sync-snapshot.json").read_text(encoding="utf-8"))
base_ok = True
for e in p2["plan"]:
    s = snap["issues"][e["graph_node_id"]]
    if (e["base"]["title"], e["base"]["remote_updated_at"], e["base"]["local_updated_at"], e["base"]["body_digest"], e["base"]["state"]) != \
       (s["title"], s["remote_updated_at"], s["local_updated_at"], s["body_digest"], s["state"]):
        base_ok = False
    if not e["issue"].get("classification"): base_ok = False
    if e["issue"]["classification"] != "unchanged": base_ok = False
checks["three_way_base_preserved"] = base_ok
if not base_ok: failures.append("3-way base was not preserved")
# 6. local graph is authority: imported title landed in graph + task file, node not deleted
graph = json.loads((F/".dev-graph/state/graph.json").read_text(encoding="utf-8"))
titles = {n["graph_node_id"]: n["title"] for n in graph["nodes"]}
checks["titles"] = titles
if titles.get("tasks/T-SYNC-001") != "Sync import target task (remote revision 2)": failures.append("import not applied locally")
if titles.get("tasks/T-SYNC-002") != "Sync export target task (local revision 2)": failures.append("local export value was overwritten")
if len(graph["nodes"]) != 2: failures.append("node count changed (physical delete?)")
if "Sync import target task (remote revision 2)" not in (F/"tasks/T-SYNC-001.md").read_text(encoding="utf-8"):
    failures.append("task file frontmatter not updated")
# 7. remote issue 102 carries the exported title; 101 untouched by us
ad = json.loads((F/"github-adapter.json").read_text(encoding="utf-8"))
checks["remote_titles"] = {k: v["title"] for k, v in ad["issues"].items()}
checks["mutation_log"] = ad["mutation_log"]
if ad["issues"]["102"]["title"] != "Sync export target task (local revision 2)": failures.append("export did not reach the remote fixture")
if len(ad["mutation_log"]) != 1 or ad["mutation_log"][0]["op"] != "issue-edit": failures.append("unexpected remote mutation set")
if ad["projects"]["delivery"]["items"] != json.loads((W/"pre"/"github-adapter.json").read_text(encoding="utf-8"))["projects"]["delivery"]["items"]:
    failures.append("project items changed unexpectedly")
# 8. containment: every gh call went to the fixture repo, no other host
calls = [json.loads(l) for l in (F/"github-adapter-calls.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()]
checks["call_ops"] = {}
for c in calls: checks["call_ops"][c["op"]] = checks["call_ops"].get(c["op"], 0) + 1
checks["mutating_calls_total"] = sum(1 for c in calls if c["mutation"])
if checks["mutating_calls_total"] != 1: failures.append("unexpected number of mutating adapter calls")
print(json.dumps({"checks": checks, "failures": failures}, ensure_ascii=False, indent=1))
print("VERDICT:", "PASS" if not failures else "FAIL")
PY

